# Existing data: every household gets one account; its transactions move to it. The opening
# balance is 0 on the day of the household's first transaction (the user corrects it later).
ACCOUNT_NAME = "Tekući račun"


def create_default_accounts(apps, schema_editor):
    Household = apps.get_model("users", "Household")
    Account = apps.get_model("finances", "Account")
    Transaction = apps.get_model("finances", "Transaction")
    for household in Household.objects.all():
        first = Transaction.objects.filter(household=household).aggregate(first=Min("date"))
        account = Account.objects.create(
            household=household,
            name=ACCOUNT_NAME,
            opening_date=first["first"] or django.utils.timezone.localdate(),
        )
        Transaction.objects.filter(household=household).update(account=account)


